// IAsyncEnumerable (C# 8+) — async lazy sequences
async IAsyncEnumerable<int> GetNumbersAsync() {
    for (int i = 0; i < 10; i++) {
        await Task.Delay(100);  // async work per item
        yield return i;
    }
}

// Consume with await foreach
